import type { ManualCatalogItemEntry } from "./types";

/**
 * Korean DP-era (Diamond & Pearl series, May 2010 - March 2011) TCG sets —
 * 10 sets, ~460 cards, none of which exist in tcgdex.net's Korean catalog
 * at all (tcgdex's KO coverage only starts years later, at Sun & Moon /
 * Sword & Shield — confirmed live, a direct id probe against every one of
 * these set names 404s). Bulbapedia is the sole source: its own "Set list"
 * wikitext table (action=parse&prop=wikitext against each "<Name> (KTCG)"
 * page, NOT just the section=0 lead the crawler in
 * scripts/crawl-pokemon-set-logos-bulbapedia.ts fetches — that crawler
 * only reads the infobox, so it never sees this table and reported these
 * sets as unseeded in scripts/data/set-logos/bulbapedia-ko.review.json).
 *
 * Single-source disclosure: unlike this repo's other manual entries (see
 * legend-secrets.ts, mega-festa-korean-promos.ts), there is no second
 * independently-corroborating source for these ~460 individual card
 * names/numbers/rarities — Bulbapedia's Set list table is the only one
 * that exists for a Korean-exclusive product line this old. It is treated
 * as authoritative here on the same basis the rest of this codebase
 * already does (crawl-pokemon-set-logos-bulbapedia.ts's whole premise is
 * that Bulbapedia's own structured data is trustworthy), not on
 * multi-source corroboration.
 *
 * Per-card Korean names are NOT available from this source — Bulbapedia's
 * Set list table only gives each card's English name (these are Korean
 * localizations of English-language Diamond & Pearl-era cards, per each
 * set's own Bulbapedia description). `name` below is therefore the
 * English name despite `language: "KR"`; `nameEn` is left unset to
 * avoid a redundant duplicate. Set.name (native Korean set title) IS
 * available and used, from each page's infobox `setname` field.
 *
 * cardType is coarse ("Pokémon" / "Trainer" / "Energy", no subtype
 * suffix) per cardTypeFromSupertype's existing non-English convention —
 * Bulbapedia's per-card energy type (Grass/Fire/Water/...) has no column
 * in this schema to hold it and is dropped, matching how
 * cardTypeFromTcgdexCategory already treats non-English rows.
 *
 * Per-set logos: 3 of these 10 sets DO have a real Bulbapedia setlogo
 * (Start of an Adventure, Burning Confrontation, Space-Time Clash) — left
 * for scripts/crawl-pokemon-set-logos-bulbapedia.ts's own crawl+derive to
 * backfill via Set.nameEn match once these Set rows exist, rather than
 * duplicated here (Set.logoUrl isn't part of ManualSetRef).
 *
 * Card counts cross-checked: every set's Set list table entry count
 * matches its infobox `cards=` field exactly (60/60, 40/40, ...).
 *
 * Sourced 2026-09-02 from bulbapedia.bulbagarden.net.
 */
